import pb from "@/lib/pb";
import { Card, CardContent } from "@/components/ui/card";

export default async function TorneoDetallePage({
  params,
}: {
  params: { id: string };
}) {
  try {
    const tournament = await pb
      .collection("tournaments")
      .getOne(params.id, {
        expand: "creator",
      });

    return (
      <div className="min-h-screen p-10 bg-gray-50 flex justify-center">
        <Card className="max-w-2xl w-full">
          <CardContent className="pt-6 space-y-4">
            <h1 className="text-3xl font-bold">
              {tournament.name}
            </h1>

            <p className="text-gray-600">
              {tournament.description}
            </p>

            <div>
              <strong>Categoría:</strong> {tournament.category}
            </div>

            <div>
              <strong>Reglas:</strong>
              <p>{tournament.rules}</p>
            </div>

            <div>
              <strong>Límite:</strong> {tournament.limit}
            </div>

            <div>
              <strong>Fecha inicio:</strong>{" "}
              {new Date(tournament.startDate).toLocaleString()}
            </div>

            <div className="text-sm text-gray-500">
              Creado por: {tournament.expand?.creator?.email}
            </div>
          </CardContent>
        </Card>
      </div>
    );
  } catch (error) {
    return (
      <div className="p-10 text-center text-red-500">
        Torneo no encontrado
      </div>
    );
  }
}